code_question:
def solution() -> int:
    N = 2
    P = [17, 8]
    def rod_cutting(price, length):
        if length == 0:
            return 0
        max_revenue = 0
        for i in range(1, length + 1):
            max_revenue = max(max_revenue, price[i-1] + rod_cutting(price, length - i))
        return max_revenue
    return rod_cutting(P, N)

