code_question:
def solution() -> int:
    import numpy as np
    W = np.array([25, 28, 1, 29])
    V = np.array([18, 15, 7, 21])
    C = 4
    n = len(W)
    K = np.zeros((n + 1, C + 1), dtype=int)
    for i in range(n + 1):
        for w in range(C + 1):
            if i == 0 or w == 0:
                K[i][w] = 0
            elif W[i-1] <= w:
                K[i][w] = max(V[i-1] + K[i-1][w-W[i-1]], K[i-1][w])
            else:
                K[i][w] = K[i-1][w]
    return int(K[n][C])

