code_question:
def solution() -> int:
    from itertools import combinations
    weights = [9, 5]
    total_sum = sum(weights)
    min_diff = float('inf')
    for i in range(1, len(weights) + 1):
        for combo in combinations(weights, i):
            current_sum = sum(combo)
            diff = abs(total_sum - 2 * current_sum)
            if diff < min_diff:
                min_diff = diff
    return int(min_diff)

