def solution() -> int:
    from itertools import combinations
    weights = [6, 29, 7, 11, 26, 24, 32, 2, 31, 3, 20, 26, 11, 11, 15, 1]
    total_sum = sum(weights)
    n = len(weights)
    min_diff = float('inf')
    for i in range(1, n // 2 + 1):
        for combo in combinations(weights, i):
            sum1 = sum(combo)
            sum2 = total_sum - sum1
            min_diff = min(min_diff, abs(sum1 - sum2))
    return int(min_diff)

