def solution() -> Dict[int, List[int]]:
    import numpy as np
    from typing import Dict, List
    # Define the available slots for each participant
    participants = {
        0: {'available_slots': [0, 1, 3], 'meetings': [0]},
        1: {'available_slots': [0, 1, 2, 3], 'meetings': [1, 0]},
        2: {'available_slots': [0, 1, 2, 3], 'meetings': [0]}
    }
    # Find the common available slots
    common_slots = set(participants[0]['available_slots'])
    for participant in participants.values():
        common_slots &= set(participant['available_slots'])
    # Convert the set to a list
    common_slots = list(common_slots)
    # Create a dictionary to map meeting numbers to time slots
    meet2time = {0: common_slots}
    return meet2time

