code_question:
def solution() -> Dict[int, List[int]]:
    import numpy as np
    from typing import Dict, List
    # Define the available slots for each participant
    participants = {
        0: {'available_slots': [1, 2], 'meetings': [0, 1]},
        1: {'available_slots': [2, 3], 'meetings': [1, 0]},
        2: {'available_slots': [0, 1, 2], 'meetings': [0]}
    }
    # Define the total number of time slots
    total_slots = 4
    # Create a matrix to represent the availability of each participant for each time slot
    availability_matrix = np.zeros((len(participants), total_slots), dtype=int)
    for participant, data in participants.items():
        for slot in data['available_slots']:
            availability_matrix[participant, slot] = 1
    # Find the common available slots
    common_slots = np.all(availability_matrix == 1, axis=0)
    # Get the list of common available slots
    common_slots_list = np.where(common_slots)[0].tolist()
    # Create a dictionary to map meeting numbers to time slots
    meet2time = {i: common_slots_list for i in range(len(participants))}
    return meet2time

