code_question:
def solution() -> Dict[int, List[int]]:
    import numpy as np
    from typing import Dict, List

    # Define the participants and their available slots
    participants = {
        0: {'available_slots': [2, 3], 'meetings': [1]},
        1: {'available_slots': [0, 2], 'meetings': [1, 0]},
        2: {'available_slots': [0, 2, 3], 'meetings': [1]}
    }

    # Create a matrix to represent the availability of each participant for each time slot
    num_participants = len(participants)
    num_slots = 4
    availability_matrix = np.zeros((num_participants, num_slots), dtype=int)

    for participant, data in participants.items():
        for slot in data['available_slots']:
            availability_matrix[participant, slot] = 1

    # Find a time slot where all participants are available
    common_slots = np.all(availability_matrix == 1, axis=0)
    available_slots = np.where(common_slots)[0]

    # If there are no common slots, return an empty dictionary
    if len(available_slots) == 0:
        return {}

    # Return the available slots for each meeting
    return {0: available_slots.tolist()}

