def solution() -> Dict[int, List[int]]:
    import numpy as np
    from typing import Dict, List
    # Define the participants and their available slots
    participants = {
        0: {'available_slots': [1, 2, 3, 4], 'meetings': [2, 1]},
        1: {'available_slots': [0, 1, 2, 3], 'meetings': [0]},
        2: {'available_slots': [1, 2], 'meetings': [0]},
        3: {'available_slots': [4], 'meetings': [1, 0, 2]}
    }
    # Create a matrix to represent the availability of each participant for each time slot
    availability_matrix = np.zeros((4, 5), dtype=int)
    for participant, data in participants.items():
        for slot in data['available_slots']:
            availability_matrix[participant, slot] = 1
    # Find the common available slots
    common_slots = np.all(availability_matrix == 1, axis=0)
    available_slots = np.where(common_slots)[0]
    # Map the available slots to the participants
    meet2time = {i: list(available_slots) for i in range(len(available_slots))}
    return meet2time

