def solution() -> Dict[int, str]:
    from typing import Dict
    # Define the graph as an adjacency list
    graph = {
        1: [2, 3, 4],
        2: [1, 5],
        3: [1],
        4: [1, 5, 6],
        5: [2, 4],
        6: [4]
    }
    # Define the colors
    colors = {}
    # Function to check if the color assignment is valid
    def is_valid(coloring, vertex, color):
        for neighbor in graph[vertex]:
            if coloring.get(neighbor) == color:
                return False
        return True
    # Function to solve the graph coloring problem
    def graph_coloring(vertex, coloring):
        if vertex == len(graph) + 1:
            return coloring
        for color in ['A', 'B']:
            if is_valid(coloring, vertex, color):
                coloring[vertex] = color
                result = graph_coloring(vertex + 1, coloring)
                if result:
                    return result
                del coloring[vertex]
        return None
    # Start coloring from vertex 1
    return graph_coloring(1, {})

